mapper.select:
SELECT 'PLACE_SAVE' AS source, pe.embedding, 5 AS weight, s.created_at FROM ( SELECT place_id, MIN(created_at) AS created_at FROM good_places WHERE user_id = #{userId}
AND created_at <= #{asOf}
GROUP BY place_id ) s JOIN place_embeddings pe ON pe.place_id = s.place_id WHERE pe.embedder_version = #{embedderVersion}
UNION ALL
SELECT 'LIKE' AS source, re.embedding, 3 AS weight, l.created_at FROM likes l JOIN review_embeddings re ON re.review_id = l.review_id WHERE l.user_id = #{userId} AND re.embedder_version = #{embedderVersion}
AND l.created_at <= #{asOf}
UNION ALL
SELECT 'OWN_REVIEW' AS source, re.embedding, CASE r.rating_score WHEN 5 THEN 4 WHEN 4 THEN 2 WHEN 2 THEN -2 WHEN 1 THEN -4 END AS weight, r.created_at FROM reviews r JOIN review_embeddings re ON re.review_id = r.id WHERE r.user_id = #{userId} AND r.rating_score IN (1, 2, 4, 5) AND re.embedder_version = #{embedderVersion}
AND r.created_at <= #{asOf}
